use super::*;

pub(crate) fn plandb_decision(args: &Args, what: String) -> crate::Decision {
    crate::Decision {
        stage: args.stage.clone().unwrap_or_default(),
        decision: what,
        clause: args.clause.clone().unwrap_or_default(),
        rationale: args.why.clone().unwrap_or_default(),
        ..Default::default()
    }
}
